pattern.structure:

interface CriticalAnalysis {
  rastreamentoId: string;  // Deve corresponder a Rastreamento.id
  insights: Insight[];
  controversias: Controversy[];
  desafios: Challenge[];
}

interface Insight {
  tipo: "primeira_ordem" | "segunda_ordem" | "terceira_ordem";
  titulo: string;
  descricao: string;
  implicacoes: string[];
  citacoes: string[];  // IDs de referências
}

interface Controversy {
  titulo: string;
  descricao: string;
  posicao_a: Position;
  posicao_b: Position;
  sintese: string;
}

interface Position {
  argumento: string;
  evidencias: string[];
  citacoes: string[];
}

interface Challenge {
  titulo: string;
  descricao: string;
  propostas: string[];
  citacoes: string[];
}

pattern.example:

{
  titulo: "Idade de início do rastreamento mamográfico",
  descricao: "O debate sobre iniciar rastreamento mamográfico aos 40 ou 50 anos permanece uma das controvérsias mais discutidas em saúde pública, com implicações significativas para políticas de rastreamento globalmente [1].",
  posicao_a: {
    argumento: "Início aos 40 anos detecta mais cânceres em estágio inicial, resultando em redução de mortalidade específica de aproximadamente 15% nessa faixa etária [2].",
    evidencias: [
      "Meta-análise com 160.000 mulheres mostrou benefício estatisticamente significativo",
      "Seguimento médio de 13 anos demonstrou persistência do benefício",
      "Canceres detectados em estágio mais precoce (I/II vs III/IV)"
    ],
    citacoes: ["jama-2024-40vs50", "nelson-2024-meta"]
  },
  posicao_b: {
    argumento: "Início aos 50 anos tem melhor relação custo-efetividade, menor taxa de falsos-positivos, e evita ansiedade desnecessária em população de menor risco [3].",
    evidencias: [
      "Análise de custo-efetividade canadense favorece início aos 50",
      "Taxa de falsos-positivos 50% menor na faixa 50-69 vs 40-49",
      "Menor número de biópsias desnecessárias"
    ],
    citacoes: ["cmaj-2024-costeff", "cochrane-2024-screening"]
  },
  sintese: "Ambas posições têm mérito científico. A decisão ideal deve considerar o contexto local (recursos, infraestrutura), preferências individuais após discussão informada, e fatores de risco específicos da paciente. Não há resposta universalmente correta [4]."
}

pattern.requirement:

// Em lib/data/rastreamentos.ts
{ id: "cancer-mama", ... }

// Em lib/data/analise-critica.ts (DEVE corresponder)
{ rastreamentoId: "cancer-mama", ... }

// ContentModeWrapper usa o mesmo ID para alternar
<ContentModeWrapper
  descriptiveContent={<RastreamentoView id="cancer-mama" />}
  criticalAnalysisContent={<CriticalAnalysisView rastreamentoId="cancer-mama" />}
/>
